import { useState } from 'react';
import {
  JxTextField,
  JxSelect,
  JxSelectItem,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [emailTouched, setEmailTouched] = useState(false);
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [successVisible, setSuccessVisible] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email.trim());
  const showEmailError = emailTouched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = () => {
    if (!canSubmit) return;
    setSuccessVisible(true);
  };

  return (
    <div
      className="jx-stack"
      style={{ maxWidth: 420, gap: 'var(--jx-space-md)' }}
    >
      {successVisible && (
        <JxAlert
          variant="success"
          onClose={() => setSuccessVisible(false)}
        >
          Приглашение отправлено на {email.trim()}.
        </JxAlert>
      )}

      <JxTextField
        label="Электронная почта"
        placeholder="name@company.com"
        value={email}
        onValueChange={(next) => setEmail(next)}
        onBlur={() => setEmailTouched(true)}
        error={showEmailError}
        helperText={
          showEmailError
            ? 'Введите корректный адрес электронной почты'
            : 'На эту почту придёт приглашение в команду'
        }
      />

      <JxSelect
        label="Роль"
        value={role}
        onValueChange={(next) => setRole(next)}
      >
        {ROLES.map((item) => (
          <JxSelectItem key={item.value} value={item.value}>
            {item.label}
          </JxSelectItem>
        ))}
      </JxSelect>

      <JxSwitch
        label="Отправить уведомление"
        value={notify}
        onValueChange={(next) => setNotify(next)}
      />

      <JxButton
        variant="primary"
        disabled={!canSubmit}
        onClick={handleSubmit}
      >
        Отправить приглашение
      </JxButton>
    </div>
  );
}

